<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$d=body();required($d,['full_name','phone']);$email=trim($d['email']??'');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))fail('Invalid email.');try{$s=db()->prepare('UPDATE users SET full_name=?,shop_name=?,phone=?,email=? WHERE id=?');$s->execute([trim($d['full_name']),trim($d['shop_name']??''),trim($d['phone']),$email?:null,$u['id']]);out(['success'=>true,'message'=>'Profile updated.']);}catch(PDOException $e){fail($e->getCode()==='23000'?'Phone or email is already in use.':'Could not update profile.',400);}
